<?php
require_once __DIR__ . '/../includes/functions.php';
$user=require_role(['Senior Citizen']);
$q=db()->prepare("SELECT q.*,CASE WHEN q.appointment_id IS NOT NULL THEN 'Appointment' ELSE CONCAT('Assistance request #',q.request_id) END AS service_type,(SELECT COUNT(*) FROM service_queue ahead WHERE ahead.queue_date=q.queue_date AND ahead.status='Waiting' AND ahead.queue_number<q.queue_number) AS people_ahead FROM service_queue q LEFT JOIN assistance_requests ar ON ar.request_id=q.request_id LEFT JOIN senior_citizens s ON s.senior_id=ar.senior_id LEFT JOIN appointments a ON a.appointment_id=q.appointment_id WHERE COALESCE(s.user_id,a.user_id)=? AND q.queue_date>=CURDATE() AND q.status IN ('Waiting','Called','Serving') ORDER BY q.queue_date,q.queue_number");
$q->execute([$user['user_id']]);$mine=$q->fetchAll();
$today=date('Y-m-d');$calledQ=db()->prepare("SELECT queue_number FROM service_queue WHERE queue_date=? AND status IN ('Called','Serving') ORDER BY queue_number");$calledQ->execute([$today]);$nowServing=$calledQ->fetchAll(PDO::FETCH_COLUMN);
require_once __DIR__ . '/../includes/header.php';require_once __DIR__ . '/../includes/sidebar.php';
?>
<main class="container-fluid py-3" style="max-width:1000px"><header class="d-flex flex-wrap justify-content-between align-items-end gap-2 mb-3"><div><h1 class="page-title mb-1">My Queue</h1><p class="text-muted mb-0">Check your ticket and queue progress before heading to the barangay office.</p></div><span class="badge text-bg-light">Updates automatically every 30 seconds</span></header>
<section class="panel mb-3"><h2 class="h5">Now serving · <?= e(date('M j, Y')) ?></h2><?php if(!$nowServing): ?><p class="text-muted mb-0">No tickets are being called right now.</p><?php else: ?><div class="d-flex flex-wrap gap-2"><?php foreach($nowServing as $number): ?><span class="badge text-bg-primary fs-5 p-2">Q-<?= e(str_pad((string)$number,4,'0',STR_PAD_LEFT)) ?></span><?php endforeach; ?></div><?php endif; ?></section>
<?php if(!$mine): ?><section class="panel"><h2 class="h5">No active queue tickets</h2><p class="mb-0">Submit an assistance request or wait for staff to confirm your appointment. A queue ticket will appear here when it is issued.</p></section><?php else: ?><div class="row g-3"><?php foreach($mine as $ticket): ?><div class="col-md-6"><article class="panel h-100"><div class="d-flex justify-content-between align-items-start gap-2"><div><small class="text-muted"><?= e($ticket['service_type']) ?> · <?= e(date('M j, Y',strtotime($ticket['queue_date']))) ?></small><h2 class="display-6 fw-bold mb-2">Q-<?= e(str_pad((string)$ticket['queue_number'],4,'0',STR_PAD_LEFT)) ?></h2></div><span class="badge text-bg-<?= $ticket['status']==='Waiting'?'warning':($ticket['status']==='Called'?'primary':'info') ?>"><?= e($ticket['status']) ?></span></div><?php if($ticket['status']==='Waiting'): ?><p class="mb-0">There <?= (int)$ticket['people_ahead']===1?'is':'are' ?> <strong><?= (int)$ticket['people_ahead'] ?></strong> waiting ticket<?= (int)$ticket['people_ahead']===1?'':'s' ?> ahead of you.</p><?php elseif($ticket['status']==='Called'): ?><p class="alert alert-primary mb-0">Your ticket is being called. Please proceed to the service counter.</p><?php else: ?><p class="mb-0">Your service is in progress.</p><?php endif; ?></article></div><?php endforeach; ?></div><?php endif; ?></main>
<meta http-equiv="refresh" content="30">
<?php require_once __DIR__ . '/../includes/footer.php'; ?>
